import sys
import signal
import time
import json
import requests
import numpy as np
from gpiozero import OutputDevice, DeviceClosed
from spidev import SpiDev, SpiDevError
from argparse import ArgumentParser
from adafruit_mcp3xxx.mcp3008 import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn

# Constants
DEFAULT_SAMPLE_RATE = 500  # Hz
DEFAULT_WINDOW_SIZE = 10
DEFAULT_THRESHOLD = 0.5
DEFAULT_HYSTERESIS = 0.05
DEFAULT_OUTPUT_PIN = 0
DEFAULT_LOG_FILE = 'sound_log.txt'
DEFAULT_API_URL = 'https://api.example.com/upload'

# Global variables
spi = None
mcp = None
sound_sensor = None
output_device = None
running = True

def cleanup(signum, frame):
    global running
    running = False
    if output_device:
        output_device.close()
    if spi:
        spi.close()
    print("Cleanup complete, exiting.")

def setup_gpio(pin):
    try:
        return OutputDevice(pin)
    except DeviceClosed:
        print(f"Failed to set up GPIO {pin}, disabling output.")
        return None

def setup_spi():
    try:
        spi = SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = 1350000
        return spi
    except SpiDevError as e:
        print(f"SPI initialization failed: {e}, using simulated data.")
        return None

def read_sound_sensor():
    if spi:
        return sound_sensor.voltage
    else:
        # Simulated data
        return np.random.rand()

def moving_average(data, window_size):
    return np.convolve(data, np.ones(window_size)/window_size, mode='valid')

def normalize(value, min_val, max_val):
    return (value - min_val) / (max_val - min_val)

def log_data(log_file, data):
    with open(log_file, 'a') as f:
        f.write(f"{time.time()}: {data}\n")

def upload_data(api_url, data):
    headers = {'Content-Type': 'application/json'}
    payload = {'data': data}
    try:
        response = requests.post(api_url, headers=headers, json=payload)
        response.raise_for_status()
    except requests.RequestException as e:
        print(f"Failed to upload data: {e}")
        return False
    return True

def main():
    global spi, mcp, sound_sensor, output_device

    parser = ArgumentParser(description="Sound sensor monitoring and logging")
    parser.add_argument('--sample-rate', type=int, default=DEFAULT_SAMPLE_RATE, help="Sampling rate in Hz")
    parser.add_argument('--window-size', type=int, default=DEFAULT_WINDOW_SIZE, help="Moving average window size")
    parser.add_argument('--threshold', type=float, default=DEFAULT_THRESHOLD, help="Threshold for output activation")
    parser.add_argument('--hysteresis', type=float, default=DEFAULT_HYSTERESIS, help="Hysteresis for output deactivation")
    parser.add_argument('--output-pin', type=int, default=DEFAULT_OUTPUT_PIN, help="Output GPIO pin (0 to disable)")
    parser.add_argument('--log-file', type=str, default=DEFAULT_LOG_FILE, help="Log file path")
    parser.add_argument('--api-url', type=str, default=DEFAULT_API_URL, help="Cloud API URL")
    parser.add_argument('--duration', type=int, default=None, help="Duration to run in seconds (None for indefinite)")
    args = parser.parse_args()

    spi = setup_spi()
    if spi:
        mcp = MCP3008(spi)
        sound_sensor = AnalogIn(mcp, mcp.channels[0])

    output_device = setup_gpio(args.output_pin) if args.output_pin else None

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    start_time = time.time()
    data_buffer = []
    last_output_state = False

    while running:
        if args.duration and time.time() - start_time > args.duration:
            break

        sample = read_sound_sensor()
        data_buffer.append(sample)

        if len(data_buffer) >= args.window_size:
            filtered_value = moving_average(data_buffer, args.window_size)[-1]
            normalized_value = normalize(filtered_value, 0, 3.3)  # Assuming 3.3V max voltage
            log_data(args.log_file, normalized_value)

            if normalized_value > args.threshold and not last_output_state:
                if output_device:
                    output_device.on()
                last_output_state = True
            elif normalized_value < args.threshold - args.hysteresis and last_output_state:
                if output_device:
                    output_device.off()
                last_output_state = False

            if not upload_data(args.api_url, normalized_value):
                time.sleep(1)  # Exponential backoff
            else:
                data_buffer = []  # Clear buffer on successful upload

        time.sleep(1 / args.sample_rate)

if __name__ == "__main__":
    main()

