import spidev
import signal
import time
import sys

class LoadCellReader:
    def __init__(self, bus=0, device=0, max_speed_hz=50000, mode=0, bits_per_word=8):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(bus, device)
            self.spi.max_speed_hz = max_speed_hz
            self.spi.mode = mode
            self.spi.bits_per_word = bits_per_word
        except (OSError, IOError) as e:
            print(f"Failed to open SPI device: {e}")
            sys.exit(1)

    def read_raw_data(self):
        try:
            # Send the three-byte command sequence
            response = self.spi.xfer2([0x01, 0x80, 0x00])
            # Extract the 10-bit result
            raw_value = ((response[1] & 0x03) << 8) | response[2]
            return raw_value
        except (OSError, IOError) as e:
            print(f"SPI read error: {e}")
            return None

    def convert_to_weight(self, raw_value):
        # Example conversion: 10-bit value to kg
        # Adjust the scale factor as needed
        scale_factor = 0.001  # Example scale factor
        weight = raw_value * scale_factor
        return weight

    def close(self):
        try:
            self.spi.close()
        except (OSError, IOError) as e:
            print(f"Failed to close SPI device: {e}")

def signal_handler(sig, frame):
    print("SIGTERM received, shutting down...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)

    load_cell = LoadCellReader()

    try:
        while True:
            raw_value = load_cell.read_raw_data()
            if raw_value is not None:
                weight = load_cell.convert_to_weight(raw_value)
                print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("KeyboardInterrupt received, shutting down...")
    finally:
        load_cell.close()
        print("SPI device closed, shutdown complete.")

