class ADS1015Controller:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.i2c = busio.I2C(board.SCL, board.SDA)
        self.ads = ADS1015(self.i2c, address=self.address)
        self.continuous_channel = None
        self.comparator_channel = None
        self.logger = logging.getLogger(__name__)
        if self.debug:
            self.logger.setLevel(logging.DEBUG)
        else:
            self.logger.setLevel(logging.ERROR)
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            self.ads.gain = pga
            self.ads.data_rate = sps
            chan = AnalogIn(self.ads, channel)
            return chan.value
        except Exception as e:
            self.logger.error(f"Error reading ADC single-ended: {e}")
            return None

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            self.ads.gain = pga
            self.ads.data_rate = sps
            self.continuous_channel = channel
        except Exception as e:
            self.logger.error(f"Error starting continuous conversion: {e}")

    def get_last_conversion_results(self):
        if self.continuous_channel is not None:
            try:
                chan = AnalogIn(self.ads, self.continuous_channel)
                return chan.value
            except Exception as e:
                self.logger.error(f"Error getting last conversion results: {e}")
                return None
        return None

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            self.ads.gain = pga
            self.ads.data_rate = sps
            self.comparator_channel = channel
            # Note: The ADS1015 does not support comparator mode directly through the library.
            # This is a placeholder for the logic you would implement to configure the comparator.
            # You would need to write to the appropriate registers to set up the comparator.
            self.logger.warning("Comparator mode is not directly supported by the adafruit_ads1x15 library.")
        except Exception as e:
            self.logger.error(f"Error starting single-ended comparator: {e}")

    def cleanup(self, signum, frame):
        self.logger.info("Cleaning up I2C resources.")
        self.i2c.deinit()
        sys.exit(0)

