import spidev
import RPi.GPIO as GPIO
import time
import logging

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    def __init__(self, spi_bus=0, spi_device=0, spi_speed=1350000, adc_channel=0, pump_gpio=18):
        self.spi = spidev.SpiDev()
        self.adc_channel = adc_channel
        self.pump_gpio = pump_gpio

        try:
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = spi_speed
            logging.info("SPI bus opened successfully.")
        except Exception as e:
            logging.error(f"Failed to open SPI bus: {e}")
            raise

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_gpio, GPIO.OUT)
            GPIO.output(self.pump_gpio, GPIO.LOW)
            logging.info("GPIO setup successfully.")
        except Exception as e:
            logging.error(f"Failed to setup GPIO: {e}")
            self.spi.close()
            raise

    def read_moisture(self):
        try:
            # Read the ADC value
            adc_value = self.spi.xfer2([1, (8 + self.adc_channel) << 4, 0])
            data = ((adc_value[1] & 3) << 8) + adc_value[2]
            return data
        except Exception as e:
            logging.error(f"SPI transaction failed: {e}")
            return None

    def run_pump(self, seconds):
        try:
            GPIO.output(self.pump_gpio, GPIO.HIGH)
            time.sleep(seconds)
            GPIO.output(self.pump_gpio, GPIO.LOW)
        except Exception as e:
            logging.error(f"Failed to run pump: {e}")

    def irrigation_cycle(self):
        moisture_value = self.read_moisture()
        if moisture_value is not None and moisture_value > 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        GPIO.cleanup()
        self.spi.close()
        logging.info("Resources released.")

def schedule_cycles(controller, cycle_count, interval_seconds):
    for i in range(cycle_count):
        result = controller.irrigation_cycle()
        logging.info(f"Irrigation cycle {i+1}: {'Pump ran' if result else 'No pump run'}")
        time.sleep(interval_seconds)

if __name__ == "__main__":
    controller = None
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, cycle_count=10, interval_seconds=3)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        if controller:
            controller.close()

