import argparse
import logging
import queue
import signal
import sys
import threading
import time
from gpiozero import DigitalInputDevice
from spidev import SpiDev
import paho.mqtt.client as mqtt

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False
        self.spi = None
        self.digital_sensors = []

        if self.sensor_type == 'digital':
            for pin in gpio_pins:
                sensor = DigitalInputDevice(pin, pull_up=True)
                self.digital_sensors.append(sensor)
        elif self.sensor_type == 'analog':
            self.spi = SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = spi_speed
        else:
            raise ValueError("Invalid sensor type. Use 'digital' or 'analog'.")

    def read_digital(self):
        for sensor in self.digital_sensors:
            if sensor.is_active:
                self.log_event(f"Digital sensor {self.sensor_id} triggered on pin {sensor.pin.number}")
                time.sleep(0.1)

    def read_analog(self):
        for channel in self.channels:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            result = ((adc[1] & 3) << 8) + adc[2]
            if result >= self.threshold:
                self.log_event(f"Analog sensor {self.sensor_id} triggered on channel {channel} with value {result}")
                time.sleep(0.1)

    def log_event(self, message):
        if self.log_queue:
            self.log_queue.put(message)
        else:
            logging.error(message)

    def run(self):
        self.running = True
        while self.running:
            if self.sensor_type == 'digital':
                self.read_digital()
            elif self.sensor_type == 'analog':
                self.read_analog()
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.running = False
        if self.spi:
            self.spi.close()
        for sensor in self.digital_sensors:
            sensor.close()

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitoring")
    parser.add_argument('--sensor_type', required=True, choices=['digital', 'analog'])
    parser.add_argument('--threshold', type=int, required=True)
    parser.add_argument('--sample_rate', type=int, required=True)
    parser.add_argument('--log_file', required=True)
    parser.add_argument('--gpio_pins', nargs='+', type=int, default=[])
    parser.add_argument('--channels', nargs='+', type=int, default=[])
    parser.add_argument('--spi_speed', type=int, default=1000000)
    parser.add_argument('--sensor_ids', nargs='+', required=True)

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.ERROR)

    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(
            sensor_id=sensor_id,
            sensor_type=args.sensor_type,
            threshold=args.threshold,
            sample_rate=args.sample_rate,
            gpio_pins=args.gpio_pins,
            channels=args.channels,
            spi_speed=args.spi_speed,
            log_queue=log_queue
        )
        sensors.append(sensor)

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        thread.start()
        threads.append(thread)

    def signal_handler(sig, frame):
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    while True:
        try:
            message = log_queue.get(timeout=1)
            logging.error(message)
        except queue.Empty:
            pass

if __name__ == "__main__":
    main()

import logging
import signal
import time
from gpiozero import DistanceSensor, Servo
from gpiozero.pins.pigpio import PiGPIOFactory
from pid import PID

class BalanceBeamController:
    def __init__(self, trigger_pin, echo_pin, servo_pin, setpoint, tolerance, max_error, max_range, servo_min, servo_max):
        self.sensor = DistanceSensor(echo=echo_pin, trigger=trigger_pin, max_distance=max_range, pin_factory=PiGPIOFactory())
        self.servo = Servo(servo_pin, min_pulse_width=servo_min, max_pulse_width=servo_max)
        self.setpoint = setpoint
        self.tolerance = tolerance
        self.max_error = max_error
        self.pid = PID(1.0, 0.1, 0.05, setpoint=setpoint)
        self.consecutive_in_tolerance = 0
        self.running = True

    def run(self):
        try:
            while self.running:
                try:
                    distance = self.sensor.distance * 100  # Convert to cm
                    error = distance - self.setpoint
                    logging.info(f"Distance: {distance:.2f} cm, Error: {error:.2f} cm")

                    if abs(error) > self.max_error:
                        logging.warning("Error exceeds maximum allowed error. Skipping PID update.")
                        continue

                    command = self.pid(error)
                    command = max(0, min(50, command))  # Limit servo travel to 0-50 degrees
                    self.servo.value = (command - 25) / 25  # Convert to servo value range
                    logging.info(f"Servo Command: {command:.2f} degrees")

                    if abs(error) <= self.tolerance:
                        self.consecutive_in_tolerance += 1
                    else:
                        self.consecutive_in_tolerance = 0

                    if self.consecutive_in_tolerance >= 3:
                        self.detach_servo()
                        logging.info("Servo detached due to consecutive in-tolerance readings.")
                        break

                except Exception as e:
