                time.sleep(0.1)

        except KeyboardInterrupt:
            logging.info("Received SIGINT. Stopping control loop.")

        finally:
            self.cleanup()

    def detach_servo(self):
        self.servo.detach()

    def cleanup(self):
        try:
            self.sensor.close()
        except Exception as e:
            logging.error(f"Failed to close sensor: {e}")

        try:
            self.servo.close()
        except Exception as e:
