from paho.mqtt import client as mqtt

# Configuration defaults
DEFAULT_CONFIG = {
    "offset": 0.0,
    "max_distance": 200.0,
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

# GPIO pin mappings
TRIGGERS = [17, 22, 24]
ECHOS = [18, 23, 25]

# Global variables
sensors = []
sensor_errors = [0] * 3
last_alert_time = 0
mqtt_client = None

def load_config():
    config = DEFAULT_CONFIG.copy()
    if os.path.exists("config.json"):
        try:
            with open("config.json", "r") as f:
                user_config = json.load(f)
                config.update(user_config)
        except (json.JSONDecodeError, IOError) as e:
            print(f"Error loading config: {e}")
    return config

def setup_sensors(config):
    global sensors
    for i in range(3):
        try:
            sensor = DistanceSensor(echo=ECHOS[i], trigger=TRIGGERS[i], max_distance=config["max_distance"])
            sensors.append(sensor)
        except Exception as e:
            print(f"Failed to initialize sensor {i+1}: {e}")
            sensors.append(None)

def read_sensors():
    distances = []
    for i, sensor in enumerate(sensors):
        if sensor is None:
            distances.append(None)
            continue
        try:
            distance = sensor.distance * 100  # Convert to cm
            if distance is not None:
                distance += config["offset"]
            distances.append(distance)
        except Exception as e:
            print(f"Error reading sensor {i+1}: {e}")
            sensor_errors[i] += 1
            if sensor_errors[i] >= 5:
                print(f"Excluding sensor {i+1} due to too many errors")
                sensors[i] = None
            distances.append(None)
    return distances

def compute_median(distances):
    valid_distances = [d for d in distances if d is not None]
    if not valid_distances:
        return None
    valid_distances.sort()
    return valid_distances[len(valid_distances) // 2]

def check_alerts(water_level):
    global last_alert_time
    if water_level is None:
        return
    if water_level < config["alert_threshold_low"]:
        if time.time() - last_alert_time > config["alert_repeat_delay"]:
            log_message(f"Alert: Water level is too low at {water_level:.2f} cm")
            last_alert_time = time.time()
    elif water_level > config["alert_threshold_high"]:
        if time.time() - last_alert_time > config["alert_repeat_delay"]:
            log_message(f"Alert: Water level is too high at {water_level:.2f} cm")
            last_alert_time = time.time()

def log_message(message):
    with open(config["log_file"], "a") as f:
        f.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - {message}\n")
    print(message)

def on_connect(client, userdata, flags, rc):
    print("Connected to MQTT broker")

def on_disconnect(client, userdata, rc):
    print("Disconnected from MQTT broker")

def setup_mqtt(config):
    global mqtt_client
    if "mqtt_broker" in config:
        mqtt_client = mqtt.Client()
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.connect(config["mqtt_broker"], 1883, 60)
        mqtt_client.loop_start()

def publish_mqtt(water_level):
    if mqtt_client is not None:
        mqtt_client.publish("home/water_level", f"{water_level:.2f}")

def cleanup():
    for sensor in sensors:
        if sensor is not None:
            sensor.close()
    if mqtt_client is not None:
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
    log_message("Shutting down")

def signal_handler(sig, frame):
    cleanup()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        config = load_config()
        setup_sensors(config)
        setup_mqtt(config)
        while True:
            distances = read_sensors()
            water_level = compute_median(distances)
            check_alerts(water_level)
            if water_level is not None:
                log_message(f"Water level: {water_level:.2f} cm")
                publish_mqtt(water_level)
            time.sleep(5)
    except Exception as e:
        print(f"Unexpected error: {e}")
        cleanup()
        sys.exit(0)

