import os
import time
import signal
import sys
from gpiozero import PWMOutputDevice
from contextlib import contextmanager

# Constants
TEMP_FILE = '/sys/class/thermal/thermal_zone0/temp'
PWM_PIN = 17
DEFAULT_PWM = 1.0
PWM_VALUES = [1.0, 0.8, 0.6, 0.4, 0.4]
TEMP_THRESHOLDS = [65, 55, 50, 45, 0]

# Validate PWM values and thresholds
if len(PWM_VALUES) != len(TEMP_THRESHOLDS):
    raise ValueError("PWM values and temperature thresholds arrays must be of equal length.")
if not all(0.0 <= pwm <= 1.0 for pwm in PWM_VALUES):
    raise ValueError("PWM values must be in the range 0.0 to 1.0.")

# Context manager for PWM device
@contextmanager
def pwm_device(pin, initial_value=DEFAULT_PWM):
    pwm = PWMOutputDevice(pin, initial_value=initial_value)
    try:
        yield pwm
    finally:
        try:
            pwm.value = DEFAULT_PWM
            pwm.close()
        except Exception as e:
            print(f"Error during cleanup: {e}", file=sys.stderr)
            sys.exit(1)

def read_cpu_temperature():
    try:
        with open(TEMP_FILE, 'r') as file:
            temp_str = file.read().strip()
            return int(temp_str) / 1000.0
    except Exception as e:
        print(f"Error reading temperature file: {e}", file=sys.stderr)
        return None

def get_pwm_for_temperature(temp):
    for threshold, pwm in zip(TEMP_THRESHOLDS, PWM_VALUES):
        if temp > threshold:
            return pwm
    return PWM_VALUES[-1]

def main():
    signal.signal(signal.SIGINT, signal.default_int_handler)
    signal.signal(signal.SIGTERM, signal.default_int_handler)

    try:
        with pwm_device(PWM_PIN) as fan:
            print("Fan control started. Running at full speed initially.")
            while True:
                temp = read_cpu_temperature()
                if temp is None:
                    pwm = DEFAULT_PWM
                else:
                    pwm = get_pwm_for_temperature(temp)
                    print(f"Current temperature: {temp:.1f}°C, Target PWM: {pwm:.1f}")

                try:
                    fan.value = pwm
                except Exception as e:
                    print(f"Error setting PWM duty: {e}", file=sys.stderr)

                time.sleep(5)
    except KeyboardInterrupt:
        print("Fan control interrupted by user.")
    finally:
        print("Fan control shutting down.")

if __name__ == "__main__":
    main()

