import os
import signal
import sys
import time
import json
import numpy as np
from gpiozero import CPUTemperature
from picamera2 import Picamera2, Preview
from paho.mqtt import client as mqtt
from adafruit_circuitpython_thermalprinter import ThermalPrinter

# Configuration file path
CONFIG_FILE = 'config.txt'

# Default configuration values
DEFAULT_CONFIG = {
    'snapshot_dir': '/home/pi/snapshots',
    'roi_x1': 0,
    'roi_y1': 0,
    'roi_x2': 640,
    'roi_y2': 480,
    'motion_threshold': 10,
    'confirmation_delay': 5,
    'temperature_threshold': 70,
    'simulated_temperature': False
}

# Global variables
camera = None
printer = None
mqtt_client = None
config = None

def load_config():
    global config
    try:
        with open(CONFIG_FILE, 'r') as file:
            config = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error loading configuration: {e}")
        config = DEFAULT_CONFIG

def initialize_camera():
    global camera
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'RGB888', "size": (640, 480)}))
        camera.start()
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

def initialize_printer():
    global printer
    try:
        printer = ThermalPrinter(
            url="socket://printer.local:9100",
            baudrate=19200,
            timeout=1.0
        )
    except Exception as e:
        print(f"Error initializing printer: {e}")
        printer = None

def initialize_mqtt():
    global mqtt_client
    try:
        mqtt_client = mqtt.Client()
        mqtt_client.connect("mqtt.eclipse.org", 1883, 60)
        mqtt_client.loop_start()
    except Exception as e:
        print(f"Error initializing MQTT: {e}")
        mqtt_client = None

def capture_frame():
    try:
        return camera.capture_array()
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def detect_motion(frame1, frame2):
    roi = frame1[config['roi_y1']:config['roi_y2'], config['roi_x1']:config['roi_x2']]
    diff = np.abs(frame1 - frame2)
    motion_pixels = np.sum(diff > config['motion_threshold'])
    total_pixels = roi.size
    motion_percentage = (motion_pixels / total_pixels) * 100
    return motion_percentage > 1

def check_temperature():
    if config['simulated_temperature']:
        return 75  # Simulated temperature
    else:
        cpu_temp = CPUTemperature()
        return cpu_temp.temperature

def save_snapshot(frame):
    try:
        timestamp = time.strftime("%Y%m%d-%H%M%S")
        filename = f"{config['snapshot_dir']}/snapshot_{timestamp}.jpg"
        camera.capture_file(filename)
        print(f"Snapshot saved: {filename}")
    except Exception as e:
        print(f"Error saving snapshot: {e}")

def handle_motion_detection():
    frame1 = capture_frame()
    if frame1 is None:
        return

    time.sleep(config['confirmation_delay'])
    frame2 = capture_frame()
    if frame2 is None:
        return

    if detect_motion(frame1, frame2):
        print("Motion detected!")
        save_snapshot(frame1)
        if mqtt_client:
            mqtt_client.publish("home/security/motion", "Motion detected!")

def handle_temperature_alert():
    temperature = check_temperature()
    if temperature > config['temperature_threshold']:
        print(f"Temperature alert: {temperature}°C")
        if printer:
            printer.print(f"Temperature alert: {temperature}°C")
        if mqtt_client:
            mqtt_client.publish("home/security/temperature", f"Temperature alert: {temperature}°C")

def signal_handler(sig, frame):
    print("Shutting down...")
    if camera:
        camera.stop()
    if mqtt_client:
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)

    load_config()
    initialize_camera()
    initialize_printer()
    initialize_mqtt()

    while True:
        handle_motion_detection()
        handle_temperature_alert()
        time.sleep(1)

if __name__ == "__main__":
    main()

import serial
import sys

class BluetoothSerial:
    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.serial = None

    def __enter__(self):
        try:
            self.serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1
            )
            return self
        except serial.SerialException as e:
            sys.stderr.write(f"Error opening serial port {self.port}: {e}\n")
            sys.exit(1)

    def __exit__(self, exc_type, exc_value, traceback):
        if self.serial:
            self.serial.close()

    def send(self, data):
        try:
            encoded_data = (f'X{data}\n').encode('utf-8')
            self.serial.write(encoded_data)
            sys.stderr.write(f"Sent {len(encoded_data)} bytes\n")
        except serial.SerialException as e:
            sys.stderr.write(f"Error writing to serial port {self.port}: {e}\n")

def main():
    with BluetoothSerial('/dev/rfcomm4', 38400) as bluetooth:
        try:
            while True:
                user_input = input("Enter message (or 'q' to quit): ").strip()
                if user_input.lower() == 'q':
                    break
                bluetooth.send(user_input)
        except KeyboardInterrupt:
            sys.stderr.write("User interrupted\n")

if __name__ == "__main__":
    main()

