class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder_path=None):
        self.display = display
        self.width = width if width is not None else display.width
        self.height = height if height is not None else display.height
        self.folder_path = folder_path
        self.gif_files = []
        self.preloaded_frames = []
        self._is_running = False
        self.logger = logging.getLogger(__name__)
        logging.basicConfig(level=logging.INFO)

        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

    def load_files(self):
        if not self.folder_path:
            raise FileNotFoundError("No folder path provided")

        self.gif_files = []
        for file in Path(self.folder_path).glob('*.gif'):
            try:
                with Image.open(file) as img:
                    if img.is_animated:
                        self.gif_files.append(file)
                    else:
                        self.logger.warning(f"{file} is not an animated GIF")
            except Exception as e:
                self.logger.error(f"Error reading {file}: {e}")

        if not self.gif_files:
            raise FileNotFoundError("No valid GIF files found")

    def preload(self):
        self.preloaded_frames = []
        for file in self.gif_files:
            try:
                with Image.open(file) as img:
                    frames = []
                    for frame in range(img.n_frames):
                        img.seek(frame)
                        frame_duration = img.info.get('duration', 100)
                        loop_count = img.info.get('loop', 0)
                        frame = img.convert('RGB')
                        frame = ImageOps.pad(frame, (self.width, self.height), color='black')
                        frames.append((frame, frame_duration, loop_count))
                    self.preloaded_frames.append(frames)
            except Exception as e:
                self.logger.error(f"Error preloading {file}: {e}")

    def play(self):
        if not self.preloaded_frames:
            return False

