import logging
import time
import smbus2
import struct

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# CRC-8 polynomial and initial value
CRC8_POLYNOMIAL = 0x31
CRC8_INITIAL = 0xFF

class DHT20:
    def __init__(self, i2c_address=0x76, i2c_bus=1):
        self.i2c_address = i2c_address
        self.i2c_bus = i2c_bus
        self.bus = None
        self.open_i2c_bus()
        time.sleep(0.5)  # Wait for power stabilization
        if not self.verify_status():
            raise RuntimeError("DHT20 status verification failed")

    def open_i2c_bus(self):
        try:
            self.bus = smbus2.SMBus(self.i2c_bus)
        except Exception as e:
            logging.error(f"Failed to open I2C bus {self.i2c_bus}: {e}")
            raise

    def verify_status(self):
        try:
            status = self.bus.read_byte_data(self.i2c_address, 0x7E)
            expected_status = 0x18  # Documented value
            if status & 0xF3 == expected_status:
                return True
            else:
                logging.error(f"Status verification failed: expected {expected_status:#04x}, got {status:#04x}")
                return False
        except Exception as e:
            logging.error(f"Failed to read status register: {e}")
            return False

    def calculate_crc8(self, data):
        crc = CRC8_INITIAL
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ CRC8_POLYNOMIAL
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc

    def read_sensor_data(self):
        for attempt in range(5):
            try:
                self.bus.write_byte(self.i2c_address, 0xAC)  # Trigger measurement
                time.sleep(0.02)  # Wait for measurement to complete
                data = self.bus.read_i2c_block_data(self.i2c_address, 0x00, 7)
                if len(data) != 7:
                    logging.warning("Incomplete data read")
                    continue

                crc = self.calculate_crc8(data[:6])
                if crc != data[6]:
                    logging.warning("CRC error")
                    continue

                raw_humidity = (data[1] << 16) | (data[2] << 8) | data[3]
                raw_temperature = (data[3] & 0x0F) << 16 | (data[4] << 8) | data[5]

                humidity = -6 + 125 * raw_humidity / 1048576
                temperature = -45 + 175 * raw_temperature / 1048576

                return temperature, humidity, False

            except smbus2.SMBusError as e:
                logging.warning(f"Bus error on attempt {attempt + 1}: {e}")
                time.sleep(2)
            except Exception as e:
                logging.error(f"Unexpected error on attempt {attempt + 1}: {e}")
                return None, None, True

        logging.error("Failed to read sensor data after 5 attempts")
        return None, None, True

    def __del__(self):
        self.cleanup()

    def cleanup(self):
        if self.bus:
            self.bus.close()
            self.bus = None

# Example usage
if __name__ == "__main__":
    try:
        dht20 = DHT20()
        temp, humidity, crc_error = dht20.read_sensor_data()
        if crc_error:
            logging.error("CRC error detected")
        else:
            logging.info(f"Temperature: {temp:.2f}°C, Humidity: {humidity:.2f}%")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        dht20.cleanup()

