import os
import sys
import time
import signal
import logging
import smbus2
from struct import unpack

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# CRC-8 polynomial and initial value
CRC8_POLYNOMIAL = 0x31
CRC8_INITIAL = 0xFF

class DHT20:
    I2C_ADDRESS = 0x76
    STATUS_REGISTER = 0x78
    STATUS_MEASUREMENT_READY = 0x80
    MEASUREMENT_COMMAND = 0xAC
    MEASUREMENT_COMMAND_MODE = 0x33

    def __init__(self, bus_number=1):
        self.bus = None
        try:
            self.bus = smbus2.SMBus(bus_number)
            self.verify_sensor()
        except Exception as e:
            logging.error(f"Failed to initialize DHT20 sensor: {e}")
            self.bus = None

    def verify_sensor(self):
        try:
            status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
            if status != 0x18:
                raise ValueError("Sensor verification failed: incorrect status register value")
        except Exception as e:
            logging.error(f"Failed to verify sensor: {e}")
            self.bus = None

    def measure(self):
        if not self.bus:
            return None, None, True

        try:
            self.bus.write_i2c_block_data(self.I2C_ADDRESS, self.MEASUREMENT_COMMAND, [self.MEASUREMENT_COMMAND_MODE])
            start_time = time.time()
            while True:
                status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
                if status & self.STATUS_MEASUREMENT_READY:
                    break
                if time.time() - start_time > 0.1:
                    logging.error("Measurement timeout")
                    return None, None, True
                time.sleep(0.01)

            data = self.bus.read_i2c_block_data(self.I2C_ADDRESS, 0x00, 6)
            crc = self.calculate_crc8(data)
            if crc != data[6]:
                logging.error("CRC error")
                return None, None, True

            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
