# Constants for sensor data validation
TEMP_MIN, TEMP_MAX = -40.0, 85.0
HUMID_MIN, HUMID_MAX = 0.0, 100.0
PRESS_MIN, PRESS_MAX = 800.0, 1200.0

# UART configuration
UART_PORT = '/dev/ttyUSB0'
UART_BAUD = 9600
UART_TIMEOUT = 1.0

# Global variable to hold the serial port
ser = None

def read_sensor_data():
    try:
        while True:
            line = ser.readline().decode('utf-8').strip()
            if not line:
                continue  # Skip empty lines

            try:
                temp, humid, press = map(float, line.split(','))
            except ValueError:
                print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - Warning: Malformed data - {line}")
                continue

            if not (TEMP_MIN <= temp <= TEMP_MAX):
                print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - Warning: Temperature out of range - {temp}°C")
                continue
            if not (HUMID_MIN <= humid <= HUMID_MAX):
                print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - Warning: Humidity out of range - {humid}%")
                continue
            if not (PRESS_MIN <= press <= PRESS_MAX):
                print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - Warning: Pressure out of range - {press}hPa")
                continue

            print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - Valid data - Temp: {temp}°C, Humidity: {humid}%, Pressure: {press}hPa")

    except serial.SerialException as e:
        print(f"Serial error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    if ser:
        ser.close()
    sys.exit(0)

def main():
    global ser
    try:
        ser = serial.Serial(UART_PORT, UART_BAUD, timeout=UART_TIMEOUT)
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        read_sensor_data()
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    finally:
        if ser:
            ser.close()

if __name__ == "__main__":
    main()

