import time
import RPi.GPIO as GPIO
import struct

# Constants
DHT22_PIN = 4
START_SIGNAL_DURATION = 0.018  # 18 ms
RESPONSE_LOW_DURATION = 0.00008  # 80 µs
RESPONSE_HIGH_DURATION = 0.00008  # 80 µs
BIT_0_DURATION = 0.00026  # 260 µs
BIT_1_DURATION = 0.00070  # 700 µs
MAX_RETRIES = 3
RETRY_DELAY = 2
SUCCESS_DELAY = 5
ERROR_DELAY = 5

# Setup GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(DHT22_PIN, GPIO.OUT)

def read_dht22():
    def send_start_signal():
        GPIO.output(DHT22_PIN, GPIO.LOW)
        time.sleep(START_SIGNAL_DURATION)
        GPIO.output(DHT22_PIN, GPIO.HIGH)
        time.sleep(0.00002)  # 20 µs

    def read_response():
        GPIO.setup(DHT22_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        start_time = time.time()
        while GPIO.input(DHT22_PIN) == GPIO.LOW:
            if time.time() - start_time > RESPONSE_LOW_DURATION:
                raise TimeoutError("Sensor response low timeout")
        while GPIO.input(DHT22_PIN) == GPIO.HIGH:
            if time.time() - start_time > RESPONSE_HIGH_DURATION:
                raise TimeoutError("Sensor response high timeout")

    def read_bits():
        bits = []
        for _ in range(40):
            start_time = time.time()
            while GPIO.input(DHT22_PIN) == GPIO.LOW:
                if time.time() - start_time > BIT_0_DURATION:
                    raise TimeoutError("Bit low timeout")
            start_time = time.time()
            while GPIO.input(DHT22_PIN) == GPIO.HIGH:
                if time.time() - start_time > BIT_1_DURATION:
                    raise TimeoutError("Bit high timeout")
            bits.append(GPIO.input(DHT22_PIN))
        return bits

    def bits_to_bytes(bits):
        bytes_data = []
        for i in range(0, len(bits), 8):
            byte = 0
            for j in range(8):
                byte = (byte << 1) | bits[i + j]
            bytes_data.append(byte)
        return bytes_data

    def verify_checksum(bytes_data):
        checksum = sum(bytes_data[:-1]) & 0xFF
        return checksum == bytes_data[-1]

    try:
        send_start_signal()
        read_response()
        bits = read_bits()
        bytes_data = bits_to_bytes(bits)
        if verify_checksum(bytes_data):
            humidity = (bytes_data[0] << 8) + bytes_data[1]
            temperature = (bytes_data[2] << 8) + bytes_data[3]
            humidity = humidity / 10.0
            temperature = temperature / 10.0
            return humidity, temperature
        else:
            raise ValueError("Checksum mismatch")
    finally:
        GPIO.setup(DHT22_PIN, GPIO.OUT)

def main():
    while True:
        retries = 0
        while retries < MAX_RETRIES:
            try:
                humidity, temperature = read_dht22()
                print(f"Temperature: {temperature:.1f} °C, Humidity: {humidity:.1f} %")
                time.sleep(SUCCESS_DELAY)
                break
            except (TimeoutError, ValueError) as e:
                retries += 1
                print(f"Attempt {retries}/{MAX_RETRIES} failed: {e}")
                if retries == MAX_RETRIES:
                    print("Max retries reached. Waiting before next attempt.")
                    time.sleep(ERROR_DELAY)
                else:
                    time.sleep(RETRY_DELAY)
        else:
            time.sleep(ERROR_DELAY)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up.")

