import time
import logging
import struct
from gpiozero import Device
from smbus2 import SMBus, i2c_msg
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.WARNING, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for DHT20 sensor
DHT20_I2C_ADDRESS = 0x76
DHT20_STATUS_REG = 0x78
DHT20_DATA_REG = 0x7D
DHT20_MEASURE_CMD = 0xAC
DHT20_MEASURE_CMD_ARG = 0x3300

# CRC-8 polynomial
CRC8_POLYNOMIAL = 0x31

class DHT20:
    def __init__(self, bus_number=1):
        self.bus = SMBus(bus_number)
        self.last_read_time = 0
        self.cached_temperature = None
        self.cached_humidity = None

    def begin(self):
        try:
            # Wait 0.5s after power-on
            time.sleep(0.5)
            # Check status register
            for _ in range(10):
                status = self.bus.read_byte_data(DHT20_I2C_ADDRESS, DHT20_STATUS_REG)
                if status & 0x80 == 0:
                    return True
                time.sleep(0.08)
            logging.warning("DHT20: Status register check failed.")
            return False
        except OSError as e:
            logging.error(f"DHT20: I2C bus error: {e}")
            return False

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_read_time < 2:
            return self.cached_temperature, self.cached_humidity, False

        for attempt in range(5):
            try:
                # Start measurement
                self.bus.write_i2c_block_data(DHT20_I2C_ADDRESS, DHT20_MEASURE_CMD, [DHT20_MEASURE_CMD_ARG >> 8, DHT20_MEASURE_CMD_ARG & 0xFF])
                time.sleep(0.01)

                # Read data
                data = self.bus.read_i2c_block_data(DHT20_I2C_ADDRESS, DHT20_DATA_REG, 7)
                if self._verify_crc(data):
                    raw_temp = (data[0] << 16) | (data[1] << 8) | data[2]
                    raw_hum = (data[3] << 16) | (data[4] << 8) | data[5]
                    temperature = -45 + 175 * raw_temp / 2**20
                    humidity = 100 * raw_hum / 2**20
                    self.cached_temperature = temperature
                    self.cached_humidity = humidity
                    self.last_read_time = current_time
                    return temperature, humidity, False
                else:
                    logging.warning("DHT20: CRC error.")
            except OSError as e:
                logging.error(f"DHT20: I2C bus error: {e}")
            time.sleep(0.01)

        logging.warning("DHT20: All measurement attempts failed.")
        return None, None, True

    def _verify_crc(self, data):
        crc = 0xFF
        for byte in data[:-1]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ CRC8_POLYNOMIAL
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc == data[-1]

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def main():
    with DHT20() as sensor:
        if not sensor.begin():
            print("Failed to initialize DHT20 sensor.")
            return 0

        try:
            while True:
                temp, hum, error = sensor.get_temperature_and_humidity()
                if error:
                    print("Failed to read temperature and humidity.")
                else:
                    print(f"Temperature: {temp:.2f} °C, Humidity: {hum:.2f} %")
                time.sleep(1)
        except (KeyboardInterrupt, SystemExit):
            print("Exiting gracefully.")
            return 0

if __name__ == "__main__":
    main()

