import os
import signal
import subprocess
import sys
import time
from gpiozero import PWMOutputDevice
from signal import SIGINT, SIGTERM

# Constants
GPIO_PIN = 14
PWM_FREQUENCY = 100  # Hz
TEMP_CHECK_INTERVAL = 5  # seconds
DEFAULT_DUTY_CYCLE = 1.0  # 100%

# Global variables
fan = None
last_duty_cycle = DEFAULT_DUTY_CYCLE

def read_cpu_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, check=True)
        temp_str = result.stdout.strip()
        temp_value = float(temp_str.split('=')[1].split('\'')[0])
        return temp_value
    except (subprocess.CalledProcessError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def set_fan_duty_cycle(duty_cycle):
    global last_duty_cycle
    if 0.0 <= duty_cycle <= 1.0:
        fan.value = duty_cycle
        last_duty_cycle = duty_cycle
    else:
        print("Invalid duty cycle value. Must be between 0.0 and 1.0.", file=sys.stderr)

def determine_duty_cycle(temp_celsius):
    # Example: Adjust duty cycle based on temperature
    if temp_celsius is None:
        return last_duty_cycle
    if temp_celsius < 50:
        return 0.0  # Off
    elif temp_celsius < 60:
        return 0.25  # 25%
    elif temp_celsius < 70:
        return 0.5  # 50%
    elif temp_celsius < 80:
        return 0.75  # 75%
    else:
        return 1.0  # 100%

def signal_handler(sig, frame):
    print("Stopping fan and exiting...")
    if fan:
        fan.off()
    sys.exit(0)

def main():
    global fan
    signal.signal(SIGINT, signal_handler)
    signal.signal(SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(GPIO_PIN, frequency=PWM_FREQUENCY)
        while True:
            temp_celsius = read_cpu_temperature()
            duty_cycle = determine_duty_cycle(temp_celsius)
            set_fan_duty_cycle(duty_cycle)
            time.sleep(TEMP_CHECK_INTERVAL)
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        if fan:
            fan.off()

if __name__ == "__main__":
    main()

