import serial
import time
import logging
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
UART_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

@contextmanager
def open_uart(port, baudrate):
    uart = None
    try:
        uart = serial.Serial(port, baudrate, timeout=1)
        yield uart
    except serial.SerialException as e:
        logging.error(f"Failed to open UART port {port}: {e}")
    finally:
        if uart and uart.is_open:
            uart.close()
            logging.info(f"Closed UART port {port}")

def read_sensor_data(uart):
    try:
        if uart.in_waiting > 0:
            line = uart.readline().decode('utf-8').strip()
            parts = line.split(',')
            if len(parts) == 2:
                try:
                    temperature = float(parts[0])
                    humidity = float(parts[1])
                    return temperature, humidity
                except ValueError:
                    logging.warning(f"Malformed data received: {line}")
    except serial.SerialException as e:
        logging.error(f"Serial read error: {e}")
    return None, None

def main():
    with open_uart(UART_PORT, BAUD_RATE) as uart:
        if uart is None:
            return

        while True:
            temperature, humidity = read_sensor_data(uart)
            if temperature is not None and humidity is not None:
                logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
                if temperature > TEMPERATURE_THRESHOLD:
                    logging.warning(f"Temperature alert: {temperature}°C exceeds {TEMPERATURE_THRESHOLD}°C")
                if humidity > HUMIDITY_THRESHOLD:
                    logging.warning(f"Humidity alert: {humidity}% exceeds {HUMIDITY_THRESHOLD}%")

            time.sleep(1)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    finally:
        logging.info("Exiting program")

