import numpy as np
from matplotlib.colors import Colormap
from contextlib import contextmanager

@contextmanager
def safe_serial(port, baudrate, timeout):
    ser = None
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        yield ser
    except serial.SerialException as e:
        print(f"Failed to open serial port {port}: {e}")
    finally:
        if ser:
            ser.close()

@contextmanager
def safe_plot():
    fig, ax = plt.subplots()
    try:
        yield fig, ax
    finally:
        plt.close(fig)

def parse_frame(line):
    try:
        values = line.strip().split(',')
        if len(values) != 768:
            return None
        frame = np.array([int(v) for v in values if v.isdigit()], dtype=np.int32)
        if len(frame) != 768:
            return None
        return frame.reshape((24, 32))
    except ValueError:
        return None

def main():
    port = "/dev/ttyUSB0"
    baudrate = 9600
    timeout = 0.1
    cmap = Colormap("inferno")
    interpolation = "nearest"

    last_frame = None

    with safe_serial(port, baudrate, timeout) as ser, safe_plot() as (fig, ax):
        try:
            while True:
                line = ser.readline().decode('utf-8', errors='ignore').strip()
                if not line:
                    continue

                frame = parse_frame(line)
                if frame is None:
                    continue

                last_frame = frame
                ax.clear()
                ax.imshow(frame, cmap=cmap, interpolation=interpolation)
                plt.pause(0.1)
        except KeyboardInterrupt:
            print("Program interrupted by user.")
        except Exception as e:
            print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

