import threading
import time
import signal
import sys
import os
from gpiozero import OutputDevice, InputDevice
from gpiozero.pins.pigpio import PiGPIOFactory
from paho.mqtt import client as mqtt

# Constants
DOG_TX_PIN = 17
DOG_RX_PIN = 18
LOG_FILE = "dog_log.txt"

# Global variables
dog_tx = None
dog_rx = None
mqtt_client = None
receive_thread = None
log_file = None
running = False

def initialize_dog():
    global dog_tx, dog_rx
    try:
        factory = PiGPIOFactory()
        dog_tx = OutputDevice(DOG_TX_PIN, pin_factory=factory)
        dog_rx = InputDevice(DOG_RX_PIN, pin_factory=factory)
    except Exception as e:
        print(f"Error initializing DOG: {e}")
        sys.exit(1)

def initialize_mqtt():
    global mqtt_client
    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_message = on_message
    mqtt_client.connect("mqtt.eclipse.org", 1883, 60)
    mqtt_client.loop_start()

def on_connect(client, userdata, flags, rc):
    print("Connected with result code "+str(rc))
    client.subscribe("dog/data")

def on_message(client, userdata, msg):
    print(f"Received message: {msg.payload.decode()}")

def receive_data():
    global running
    while running:
        if dog_rx.is_active:
            data = dog_rx.value
            with open(LOG_FILE, 'a') as log:
                log.write(f"{data}\n")
        time.sleep(0.1)

def start_logging(filename):
    global running, receive_thread, log_file
    if running:
        print("Logging already in progress.")
        return
    try:
        log_file = open(filename, 'w')
        log_file.close()
        running = True
        receive_thread = threading.Thread(target=receive_data)
        receive_thread.start()
    except Exception as e:
        print(f"Error starting logging: {e}")

def stop_logging():
    global running, receive_thread
    if not running:
        print("Logging is not in progress.")
        return
    running = False
    if receive_thread:
        receive_thread.join()
        receive_thread = None

def display_log():
    try:
        with open(LOG_FILE, 'r') as log:
            print(log.read())
    except FileNotFoundError:
        print("Log file does not exist.")
    except Exception as e:
        print(f"Error reading log file: {e}")

def send_data(data):
    try:
        dog_tx.on()
        time.sleep(0.1)
        dog_tx.off()
        mqtt_client.publish("dog/data", data)
    except Exception as e:
        print(f"Error sending data: {e}")

def write_to_log(data):
    try:
        with open(LOG_FILE, 'a') as log:
            log.write(f"{data}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def help_command(command=None):
    if command == "start":
        print("Usage: start <filename>")
    elif command == "stop":
        print("Usage: stop")
    elif command == "help":
        print("Usage: help [command]")
    elif command == "display":
        print("Usage: display")
    elif command == "send":
        print("Usage: send <data>")
    elif command == "write":
        print("Usage: write <data>")
    elif command == "exit":
        print("Usage: exit")
    else:
        print("Available commands: start, stop, help, display, send, write, exit")

def signal_handler(sig, frame):
    stop_logging()
    if dog_tx:
        dog_tx.close()
    if dog_rx:
        dog_rx.close()
    if mqtt_client:
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
    print("Exiting...")
    sys.exit(0)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_dog()
