import time
import signal
import sys
from datetime import datetime
from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIODeviceError

class OccupancyMonitor:
    def __init__(self, pin=17, debounce_interval=2.0, sample_count=10):
        self.pin = pin
        self.debounce_interval = debounce_interval
        self.sample_count = sample_count
        self.detections = []
        self.sensor = None
        self.running = False

        try:
            self.sensor = DigitalInputDevice(pin, pull_up=True)
        except GPIODeviceError as e:
            print(f"Failed to initialize sensor: {e}", file=sys.stderr)
            sys.exit(1)

    def start(self):
        self.running = True
        try:
            while self.running and len(self.detections) < self.sample_count:
                if self.sensor.is_active:
                    self._handle_detection()
                time.sleep(0.5)
        except Exception as e:
            print(f"Runtime error: {e}", file=sys.stderr)
            self.running = False
        finally:
            self._cleanup()

    def _handle_detection(self):
        if not self.detections or (datetime.now() - self.detections[-1]).total_seconds() > self.debounce_interval:
            self.detections.append(datetime.now())

    def get_occupancy_stats(self):
        return {
            'total_detections': len(self.detections),
            'detection_times': self.detections
        }

    def _cleanup(self):
        if self.sensor:
            self.sensor.close()

    def stop(self):
        self.running = False

def signal_handler(sig, frame):
    print("Received signal to stop.")
    monitor.stop()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    monitor = OccupancyMonitor()
    monitor.start()

    stats = monitor.get_occupancy_stats()
    print("Occupancy Summary Report:")
    print(f"Total Detections: {stats['total_detections']}")
    print("Detection Times:")
    for dt in stats['detection_times']:
        print(dt.isoformat())

