import time
import signal
import sys
import os
from gpiozero import I2CDevice
from adafruit_bme280 import Adafruit_BME280_I2C

# Constants
I2C_ADDRESS = 0x23  # BH1750 default address
I2C_BUS = 1  # I2C bus number
MEASUREMENT_DELAY = 0.12  # 120 ms delay after triggering a measurement
PRINT_INTERVAL = 3  # Print every 3 seconds

# Global variables
i2c_device = None

def signal_handler(sig, frame):
    print("Received signal to exit. Cleaning up...")
    if i2c_device:
        i2c_device.close()
    sys.exit(0)

def initialize_i2c():
    global i2c_device
    try:
        i2c_device = I2CDevice(I2C_BUS, I2C_ADDRESS)
    except OSError as e:
        print(f"Error initializing I2C device: {e}")
        sys.exit(1)

def trigger_measurement():
    try:
        # Send measurement command (0x10 for high-resolution mode)
        i2c_device.write(bytes([0x10]))
    except OSError as e:
        print(f"Error triggering measurement: {e}")
        return False
    return True

def read_illuminance():
    try:
        # Wait for the measurement to complete
        time.sleep(MEASUREMENT_DELAY)
        # Read the result (2 bytes)
        result = i2c_device.read(2)
        # Convert the result to lux
        illuminance = (result[0] << 8 | result[1]) / 1.2
        return illuminance
    except OSError as e:
        print(f"Error reading illuminance: {e}")
        return None

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_i2c()

    try:
        while True:
            if trigger_measurement():
                illuminance = read_illuminance()
                if illuminance is not None:
                    print(f"Illuminance: {illuminance:.2f} lux")
            else:
                print("Failed to trigger measurement.")
            time.sleep(PRINT_INTERVAL)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        if i2c_device:
            i2c_device.close()

if __name__ == "__main__":
    main()

import logging
import signal
import time
import zmq
from gpiozero import PWMOutputDevice, DigitalOutputDevice
from gpiozero.pins.pigpio import PiGPIOFactory
from datetime import datetime, timedelta

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class PIDHandler:
    def __init__(self, pwm_flag=True):
        self.pwm_flag = pwm_flag
        self.global_err_state = False
        self.last_msg = datetime.now()
        self.watchdog_timeout = timedelta(seconds=20)
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.SUB)
        self.socket.setsockopt_string(zmq.SUBSCRIBE, "")
        self.socket.connect("tcp://localhost:5555")
        self.setup_gpio()

    def setup_gpio(self):
        try:
            factory = PiGPIOFactory()
            if self.pwm_flag:
                self.error_output = PWMOutputDevice(pin=12, frequency=1000, initial_value=0.0, pin_factory=factory)
            else:
                self.error_output = DigitalOutputDevice(pin=10, active_high=True, initial_value=False, pin_factory=factory)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self.error_output = None

    def update_error_output(self):
        if self.error_output:
            self.error_output.value = self.global_err_state

    def set_error_output(self, state: bool):
        if self.error_output:
            self.error_output.value = state

    def handle_message(self):
        try:
            if self.socket.poll(timeout=0):
                message = self.socket.recv_string()
                logging.info(f"Received message: {message}")
                self.last_msg = datetime.now()
                # Process subscription callbacks here
            else:
                if datetime.now() - self.last_msg > self.watchdog_timeout:
                    logging.warning("Watchdog timeout triggered")
                    self.set_error_output(True)
        except Exception as e:
            logging.error(f"Error handling message: {e}")

    def cleanup(self):
        if self.error_output:
            self.error_output.close()
        self.socket.close()
        self.context.term()
        logging.info("Resources cleaned up")

def signal_handler(sig, frame):
    logging.info("Signal received, cleaning up")
    pid_handler.cleanup()
    exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    pid_handler = PIDHandler(pwm_flag=True)

    try:
        while True:
            pid_handler.handle_message()
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        pid_handler.cleanup()

