from gpiozero import OutputDevice, Device, PinInvalidPin, PinFixedPull, PinPWMUnsupported, PinSetInput
from time import sleep
from typing import Optional

class GPIOError(Exception):
    """Custom exception for GPIO-related errors."""
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise ValueError("pin_number must be between 0 and 31")
        if initial_value not in (0, 1):
            raise ValueError("initial_value must be 0 or 1")

        try:
            self.device = OutputDevice(pin=pin_number, initial_value=initial_value)
        except (PinInvalidPin, PinFixedPull, PinPWMUnsupported, PinSetInput) as e:
            raise GPIOError(f"Failed to initialize GPIO pin {pin_number}: {e}")

    def set_value(self, value: int):
        if value not in (0, 1):
            raise ValueError("value must be 0 or 1")
        try:
            self.device.value = value
        except (PinInvalidPin, PinFixedPull, PinPWMUnsupported, PinSetInput) as e:
            raise GPIOError(f"Failed to set GPIO pin value: {e}")

    def shutdown(self):
        try:
            self.device.close()
        except (PinInvalidPin, PinFixedPull, PinPWMUnsupported, PinSetInput) as e:
            print(f"Warning: Failed to cleanly shut down GPIO pin: {e}")

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 0)
        for _ in range(10):
            pin.set_value(1)
            sleep(0.5)
            pin.set_value(0)
            sleep(0.5)
    except GPIOError as e:
        print(f"GPIO Error: {e}")
    finally:
        pin.shutdown()

