        user_input = input("Enter fan speed (0-100) or 'q' to quit: ").strip().lower()
        if user_input == 'q':
            return None
        try:
            speed = int(user_input)
            if 0 <= speed <= 100:
                return speed
            else:
                print("Please enter a number between 0 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")

try:
    while True:
        speed = get_fan_speed()
        if speed is None:
            break
        fan.value = speed / 100.0
        print(f"Fan speed set to {speed}%")
except KeyboardInterrupt:
    print("\nKeyboard interrupt received. Exiting gracefully...")
finally:
    fan.off()
    Device.cleanup()
    print("GPIO resources released.")

import time
import threading
from gpiozero import Button
from gpiozero.pins.pigpio import PiGPIOFactory

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None, debounce_time=0.005):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.debounce_time = debounce_time
        self.counter = 0
        self.last_clk_state = False
        self.factory = PiGPIOFactory()
        self.clk = Button(clk_pin, pull_up=True, pin_factory=self.factory)
        self.dt = Button(dt_pin, pull_up=True, pin_factory=self.factory)

        if self.callback is not None and not callable(self.callback):
            raise ValueError("Callback must be callable")

        self.clk.when_pressed = self._handle_clk_edge
        self.clk.when_released = self._handle_clk_edge

    def _handle_clk_edge(self):
        time.sleep(self.debounce_time)
        current_clk_state = self.clk.is_pressed
        current_dt_state = self.dt.is_pressed

        if current_clk_state != self.last_clk_state:
            if current_clk_state and current_dt_state:
                self.counter += 1
            elif current_clk_state and not current_dt_state:
                self.counter -= 1

            self.last_clk_state = current_clk_state

            if self.callback:
                try:
                    self.callback(self.counter)
                except Exception as e:
                    print(f"Error in callback: {e}")

    def cleanup(self):
        self.clk.close()
        self.dt.close()

if __name__ == "__main__":
    def on_rotation(counter):
        print(f"Counter: {counter}")

    try:
        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=on_rotation)
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        encoder.cleanup()
        print("Resources released.")

