from gpiozero.exc import GPIOZeroError

def main():
    try:
        led = LED(17)  # GPIO17 is connected to physical pin 11

        while True:
            try:
                led.on()
                print("LED is ON")
                time.sleep(1)
                led.off()
                print("LED is OFF")
                time.sleep(1)
            except GPIOZeroError as e:
                print(f"GPIOZeroError: {e}")
