from gpiozero import LED, OutputDeviceError
from gpiozero.pins.pigpio import PiGPIOFactory

class LEDController:
    def __init__(self, pin_number):
        try:
            self.led = LED(pin_number, pin_factory=PiGPIOFactory())
        except OutputDeviceError as e:
            print(f"Error initializing LED on pin {pin_number}: {e}")
            sys.exit(1)
        except ValueError as e:
            print(f"Invalid pin number {pin_number}: {e}")
            sys.exit(1)

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Blink durations must be non-negative.")
        self.led.blink(on_time=on_duration, off_time=off_duration)

def signal_handler(sig, frame):
    print("\nReceived termination signal, turning off LED and exiting.")
    led_controller.off()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led_controller = LEDController(25)
        while True:
            led_controller.blink(1.0, 0.5)
    except ValueError as e:
        print(f"ValueError: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        led_controller.off()

