        for i in range(NUM_READINGS):
            try:
                for attempt in range(MAX_RETRIES + 1):
                    try:
                        reading = simulate_sensor_read()
                        break
                    except IOError as e:
                        if attempt == MAX_RETRIES:
                            raise
                        print(f"Attempt {attempt + 1} failed: {e}. Retrying...")
                        time.sleep(1)
