def simulate_amplitude(is_vibrating):
    """Simulate an amplitude based on whether the sensor detects vibration."""
    if is_vibrating:
        return random.uniform(6.0, 9.0)
    else:
        return random.uniform(3.0, 5.0)

def main():
    try:
        # Setup the GPIO pin with internal pull-up
        sensor = DigitalInputDevice(GPIO_PIN, pull_up=True)

        # Collect samples
        amplitudes = []
        for _ in range(SAMPLE_COUNT):
            is_vibrating = not sensor.value  # Active-low sensor
            amplitude = simulate_amplitude(is_vibrating)
            amplitudes.append(amplitude)
            time.sleep(SAMPLE_INTERVAL)

        # Calculate the running average
        average_amplitude = sum(amplitudes) / SAMPLE_COUNT

        # Determine maintenance recommendation
        if average_amplitude > THRESHOLD:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        # Cleanup
        sensor.close()
        print("GPIO resources released.")

