    return random.randint(60, 100)

def read_spo2():
    return random.randint(95, 99)

def run_schedule(head_angle, foot_angle, dose_A, dose_B, interval_seconds):
    if not (60 <= interval_seconds <= 300):
        raise ValueError("Interval must be between 60 and 300 seconds")

    try:
        adjust_bed(1, head_angle)
        adjust_bed(2, foot_angle)
        dispense_medication(1, dose_A)
        dispense_medication(2, dose_B)

        heart_rate = read_heart_rate()
        spo2 = read_spo2()

        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2}%")
    except ValueError as e:
        print(f"Error: {e}")

def cleanup():
    for motor in motors.values():
        for pin in motor:
            pin.close()
    print("GPIO pins cleaned up")

def signal_handler(sig, frame):
    cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

