class MotorError(Exception):
    """Custom exception for Motor class errors."""
    pass

class Motor:
    def __init__(self, driver_lib, pin):
        if not hasattr(driver_lib, 'pi') or not callable(getattr(driver_lib.pi, 'set_mode', None)):
            raise MotorError("Invalid or disconnected driver library instance.")

        self.driver_lib = driver_lib
        self.pin = pin
        self.driver_lib.pi.set_mode(self.pin, GPIO.OUTPUT)

        self.pwm = GPIO.PWM(self.pin, 1000)  # Set frequency to 1000 Hz
        self.pwm.start(0)  # Initialize duty cycle to 0

