        try:
            self.pwm.ChangeDutyCycle(duty)
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle: {e}")

    def stop(self):
        self.set_duty_cycle(0)

    def close(self):
        self.stop()
        self.pwm.stop()
        GPIO.cleanup(self.pin)

