        try:
            duty_cycle = self._angle_to_duty_cycle(angle)
            self.servo.value = duty_cycle
            logging.info(f"Moved servo to {angle} degrees")
        except Exception as e:
            logging.error(f"Failed to move servo to {angle} degrees: {e}")

    def stop(self):
        try:
            self.servo.value = None
            logging.info("Servo stopped")
        except Exception as e:
            logging.error(f"Failed to stop servo: {e}")

