from pymodbus.client.sync import ModbusSerialClient as ModbusClient
from pymodbus.exceptions import ModbusIOException, ConnectionException

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ModbusServoMotorController:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.client = None
        self.register_map = {
            'position': {'R/W': 'R', 'Register': 0x0001, 'functioncode': 3},
            'speed': {'R/W': 'W', 'Register': 0x0002, 'functioncode': 6},
            'torque': {'R/W': 'W', 'Register': 0x0003, 'functioncode': 16}
        }
        self._setup_client()

    def _setup_client(self):
        try:
            self.client = ModbusClient(method='rtu', port=self.port, baudrate=self.baudrate, timeout=self.timeout)
            self.client.connect()
            if not self.client.is_socket_open():
                raise ConnectionException("Failed to connect to Modbus device")
        except (ConnectionException, serial.SerialException) as e:
            logger.warning(f"Failed to initialize Modbus client: {e}")
            self.client = None

    def read_register(self, register_name):
        if not self.client:
            logger.warning("Modbus client is not initialized")
            return None

        register_info = self.register_map.get(register_name)
        if not register_info or register_info['R/W'] != 'R':
            logger.warning(f"Register {register_name} is not readable")
            return None

        try:
            response = self.client.read_holding_registers(address=register_info['Register'], count=1, unit=1)
            if response.isError():
                raise ModbusIOException("Modbus read error")
            return response.registers[0]
        except (ModbusIOException, ConnectionException) as e:
            logger.warning(f"Failed to read register {register_name}: {e}")
            return None

    def write_register(self, register_name, value):
        if not self.client:
            logger.warning("Modbus client is not initialized")
            return False

        register_info = self.register_map.get(register_name)
        if not register_info or register_info['R/W'] != 'W':
            logger.warning(f"Register {register_name} is not writable")
            return False

        try:
            if register_info['functioncode'] == 6:
                response = self.client.write_register(address=register_info['Register'], value=value, unit=1)
            elif register_info['functioncode'] == 16:
                response = self.client.write_registers(address=register_info['Register'], values=[value], unit=1)
            else:
                logger.warning(f"Unsupported function code {register_info['functioncode']}")
                return False

            if response.isError():
                raise ModbusIOException("Modbus write error")
            return True
        except (ModbusIOException, ConnectionException) as e:
            logger.warning(f"Failed to write to register {register_name}: {e}")
            return False

    def close(self):
        if self.client and self.client.is_socket_open():
            self.client.close()

def signal_handler(sig, frame):
    logger.info("Received signal to exit")
    if 'controller' in globals():
        controller.close()
    exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        controller = ModbusServoMotorController()
        position = controller.read_register('position')
        if position is not None:
            logger.info(f"Current position: {position}")

        success = controller.write_register('speed', 100)
        if success:
            logger.info("Speed set successfully")
    finally:
        if 'controller' in globals():
            controller.close()

