import signal
import sys
import logging
from gpiozero import OutputDevice
from pymodbus.client.sync import ModbusSerialClient as ModbusClient
from pymodbus.exceptions import ModbusIOException, ModbusConnectionException

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ModbusServoMotor:
    def __init__(self, port='/dev/serial0', baudrate=115200, address=1):
        self.port = port
        self.baudrate = baudrate
        self.address = address
        self.client = None
        self._setup()

    def _setup(self):
        try:
            self.client = ModbusClient(method='rtu', port=self.port, baudrate=self.baudrate, stopbits=1, bytesize=8, parity='N')
            self.client.connect()
            if not self.client.is_socket_open():
                raise IOError("Failed to open serial port")
            logging.info(f"Modbus RTU client initialized on {self.port} at {self.baudrate} baud")
        except (IOError, ModbusConnectionException) as e:
            logging.error(f"Failed to initialize Modbus RTU client: {e}")
            sys.exit(1)

    def move_motor(self, position):
        if not (0 <= position <= 1000):
            logging.error("Position must be between 0 and 1000")
            return -1
        try:
            response = self.client.write_register(0, position, unit=self.address)
            if response.isError():
                logging.error(f"Modbus error: {response}")
                return -2
            logging.info(f"Motor moved to position {position}")
            return 0
        except ModbusIOException as e:
            logging.error(f"Modbus I/O error: {e}")
            return -3

    def read_position(self):
        try:
            response = self.client.read_holding_registers(0, 1, unit=self.address)
            if response.isError():
                logging.error(f"Modbus error: {response}")
                return -1, None
            position = response.registers[0]
            logging.info(f"Current motor position: {position}")
            return 0, position
        except ModbusIOException as e:
            logging.error(f"Modbus I/O error: {e}")
            return -2, None

    def cleanup(self):
        if self.client and self.client.is_socket_open():
            self.client.close()
            logging.info("Modbus RTU client closed")

def signal_handler(sig, frame):
    logging.info("Received signal to exit")
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        motor = ModbusServoMotor()
        motor.move_motor(500)
        status, position = motor.read_position()
        if status == 0:
            logging.info(f"Motor position confirmed: {position}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        motor.cleanup()

