import sys

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize GPIO devices
pump = None
light = None

def initialize_gpio():
    global pump, light
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
    except GPIOZeroError as e:
        logging.error(f"Failed to initialize GPIO devices: {e}")
        sys.exit(1)

def cleanup_gpio():
    if pump:
        pump.close()
    if light:
        light.close()
    logging.info("GPIO devices cleaned up.")

def keyword_match(phrase, keywords):
    return any(keyword in phrase.lower() for keyword in keywords)

def parse_intent(phrase):
    if keyword_match(phrase, ["pump on"]):
        return "pump_on"
    elif keyword_match(phrase, ["pump off"]):
        return "pump_off"
    elif keyword_match(phrase, ["light", "toggle"]):
        return "light_toggle"
    else:
        return "unknown"

def execute_intent(intent):
    if intent == "pump_on":
        pump.on()
        logging.info("Pump turned on.")
    elif intent == "pump_off":
        pump.off()
        logging.info("Pump turned off.")
    elif intent == "light_toggle":
        light.toggle()
        logging.info("Light toggled.")
    else:
        logging.warning(f"Unknown intent: {intent}")

def signal_handler(sig, frame):
    logging.info("Received signal to exit.")
    cleanup_gpio()
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command"
    ]

    for phrase in phrases:
        intent = parse_intent(phrase)
        logging.info(f"Parsed phrase: '{phrase}' with intent: '{intent}'")
        execute_intent(intent)

    cleanup_gpio()

if __name__ == "__main__":
    main()

