import os
import time
import signal
import sys
from gpiozero import DigitalOutputDevice

class AimingController:
    def __init__(self, ld, hd):
        self.ld = ld
        self.hd = hd
        self.laser = DigitalOutputDevice(17)
        self.hx = [133, 128, 122, 133, 128, 122, 133, 128, 122, 128]
        self.vy = [75, 75, 75, 72, 72, 72, 68, 68, 68, 90]
        self.servoblaster = None
        self.setup_servoblaster()

    def setup_servoblaster(self):
        try:
            self.servoblaster = open('/dev/servoblaster', 'w')
        except IOError as e:
            print(f"Error opening /dev/servoblaster: {e}")
            sys.exit(1)

    def set_servo_position(self, channel, position):
        try:
            self.servoblaster.write(f"{channel}={position}\n")
            self.servoblaster.flush()
        except IOError as e:
            print(f"Error writing to /dev/servoblaster: {e}")
            self.cleanup()
            sys.exit(1)

    def aim_blocks(self, nums):
        sorted_indices = sorted(range(len(nums)), key=lambda k: nums[k])
        for index in sorted_indices:
            time.sleep(self.ld / 2)
            self.set_servo_position(0, self.hx[index])
            self.set_servo_position(1, self.vy[index])
            time.sleep(self.ld / 2)
            self.laser.on()
            time.sleep(self.hd)
            self.laser.off()

    def cleanup(self):
        self.laser.off()
        if self.servoblaster:
            self.servoblaster.close()

    def __del__(self):
        self.cleanup()

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    controller = AimingController(ld=1.0, hd=0.5)
    try:
        controller.aim_blocks([5, 3, 8, 1, 4])
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        controller.cleanup()

