import io
import sys
import time
from datetime import datetime, timezone
from gpiozero import I2CDevice
from struct import pack, unpack

class DS1338:
    I2C_ADDRESS = 0x68
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06

    def __init__(self, bus=1):
        try:
            self.device = I2CDevice(bus, self.I2C_ADDRESS)
        except IOError as e:
            raise IOError(f"Failed to open I2C bus {bus} for device at address {self.I2C_ADDRESS}") from e

    def close(self):
        self.device.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def _bcd_to_dec(self, bcd):
        return (bcd & 0x0F) + ((bcd >> 4) * 10)

    def _dec_to_bcd(self, dec):
        return ((dec // 10) << 4) + (dec % 10)

    def _read_register(self, reg):
        try:
            with self.device as i2c:
                i2c.write(bytes([reg]))
                return i2c.read(1)[0]
        except IOError as e:
            raise IOError(f"Failed to read from register {reg}") from e

    def _write_register(self, reg, value):
        try:
            with self.device as i2c:
                i2c.write(bytes([reg, value]))
        except IOError as e:
            raise IOError(f"Failed to write to register {reg}") from e

    def read_all(self):
        try:
            with self.device as i2c:
                i2c.write(bytes([self.REG_SECONDS]))
                data = i2c.read(7)
        except IOError as e:
            raise IOError(f"Failed to read from registers") from e

        seconds = self._bcd_to_dec(data[0] & 0x7F)  # Mask CH bit
        minutes = self._bcd_to_dec(data[1])
        hours = self._bcd_to_dec(data[2] & 0x3F)  # Mask 12/24-hour bit
        day = self._bcd_to_dec(data[3])
        date = self._bcd_to_dec(data[4])
        month = self._bcd_to_dec(data[5])
        year = self._bcd_to_dec(data[6]) + 2000  # Assume years 2000-2099

        return (year, month, date, day, hours, minutes, seconds)

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (2000 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (1 <= day <= 7):
            raise ValueError("Day must be between 1 and 7")
        if not (0 <= hours < 24):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes < 60):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds < 60):
            raise ValueError("Seconds must be between 0 and 59")

        seconds_bcd = self._dec_to_bcd(seconds) & 0x7F  # Clear CH bit
        minutes_bcd = self._dec_to_bcd(minutes)
        hours_bcd = self._dec_to_bcd(hours) & 0x3F  # Clear 12/24-hour bit
        day_bcd = self._dec_to_bcd(day)
        date_bcd = self._dec_to_bcd(date)
        month_bcd = self._dec_to_bcd(month)
        year_bcd = self._dec_to_bcd(year - 2000)

        try:
            with self.device as i2c:
                i2c.write(bytes([self.REG_SECONDS, seconds_bcd, minutes_bcd, hours_bcd, day_bcd, date_bcd, month_bcd, year_bcd]))
        except IOError as e:
            raise IOError(f"Failed to write to registers") from e

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_datetime(datetime.now(timezone.utc))

if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            current_time = rtc.read_datetime()
            print(f"Current time: {current_time}")
    except IOError as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(0)

