import serial
import time
import signal
import sys

class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial = None
        self._open_uart()

    def _open_uart(self):
        try:
            self.serial = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
        except serial.SerialException as e:
            print(f"Failed to open UART port {self.port}: {e}")
            sys.exit(1)

    def _send_command(self, command, terminator=b'OK', timeout=1.0):
        if not self.serial:
            return None

        try:
            self.serial.write((command + '\r\n').encode())
            self.serial.flush()
            response = bytearray()
            start_time = time.time()

            while time.time() - start_time < timeout:
                if self.serial.in_waiting > 0:
                    response += self.serial.read(self.serial.in_waiting)
                    if any(terminator in response for terminator in [b'OK', b'ERROR', b'FAIL']):
                        return response
                time.sleep(0.1)

            print(f"Timeout waiting for response to command: {command}")
            return None
        except serial.SerialException as e:
            print(f"Serial error: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT')
        return b'OK' in response

    def restart(self):
        self._send_command('AT+RST')
        time.sleep(2)  # Wait for reboot
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command, timeout=10.0)
        return b'OK' in response

    def disconnect_wifi(self):
        response = self._send_command('AT+CWQAP')
        return b'OK' in response

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        if response:
            lines = response.decode().split('\r\n')
            for line in lines:
                if 'STAIP' in line:
                    return line.split(':')[1].strip()
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        headers = headers or {}
        headers['Host'] = host
        request = f"{method} {url} HTTP/1.1\r\n"
        request += "\r\n".join(f"{key}: {value}" for key, value in headers.items())
        request += "\r\n\r\n"
        if data:
            request += data

        if not self._send_command(f'AT+CIPSTART="TCP","{host}",{port}'):
            return None

        if not self._send_command(f'AT+CIPSEND={len(request)}'):
            return None

        self.serial.write(request.encode())
        self.serial.flush()

        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        response = bytearray()
        start_time = time.time()

        while time.time() - start_time < timeout:
            if self.serial.in_waiting > 0:
                response += self.serial.read(self.serial.in_waiting)
                if b'+IPD,' in response:
                    ipd_index = response.find(b'+IPD,')
                    length_start = ipd_index + len(b'+IPD,')
                    length_end = response.find(b':', length_start)
                    length = int(response[length_start:length_end])
                    data_start = length_end + 1
                    if len(response) >= data_start + length:
                        return response[data_start:data_start + length]
                if b'CLOSED' in response:
                    print("Connection closed")
                    return None
            time.sleep(0.1)

        print("Timeout waiting for HTTP response")
        return None

    def close(self):
        if self.serial:
            self.serial.close()

def signal_handler(sig, frame):
    print("Exiting gracefully")
    esp8266.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    esp8266 = ESP8266Controller()

    try:
        if esp8266.test_connection():
            print("ESP8266 is connected")
            if esp8266.restart():
                print("ESP8266 restarted")
                if esp8266.connect_wifi('your_ssid', 'your_password'):
                    print("Connected to Wi-Fi")
                    ip = esp8266.get_ip()
                    if ip:
                        print(f"IP address: {ip}")
                        response = esp8266.send_http_request('GET', '/', 'example.com')
                        if response:
                            print("HTTP response received")
                            print(response.decode())
                        else:
                            print("Failed to send HTTP request")
                    else:
                        print("Failed to get IP address")
                else:
                    print("Failed to connect to Wi-Fi")
            else:
                print("Failed to restart ESP8266")
        else:
            print("ESP8266 is not connected")
    finally:
        esp8266.close()

