import sys
import logging

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Setup GPIO
alarm_pin = gpiozero.OutputDevice(18, initial_value=False)

# Setup serial
try:
    ser = serial.Serial('/dev/ttyUSB0', baudrate=9600, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE, timeout=1)
except serial.SerialException as e:
    logging.error(f"Failed to open serial port: {e}")
    sys.exit(1)

def read_and_process_data():
    while True:
        try:
            line = ser.readline().decode('ascii').strip()
            if not line.isnumeric():
                logging.warning(f"Skipping non-numeric data: {line}")
                continue

            radiation_level = float(line)
            print(f"Radiation level: {radiation_level:.2f} µSv/h")

            if radiation_level > 50.0:
                if not alarm_pin.is_active:
                    alarm_pin.on()
                    logging.info("Alarm activated: Radiation level exceeded 50.0 µSv/h")
            else:
                if alarm_pin.is_active:
                    alarm_pin.off()
