        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial: Optional[serial.Serial] = None

    def connect(self) -> None:
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to GPS module on {self.port}")
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS module: {e}")

    def disconnect(self) -> None:
        if self.serial and self.serial.is_open:
            self.serial.close()
            logging.info("Disconnected from GPS module")

    def parse_gpgga(self, sentence: str) -> Optional[GPSReading]:
        fields = sentence.split(',')
        if len(fields) != 15 or fields[0] != '$GPGGA':
            logging.warning(f"Invalid GPGGA sentence: {sentence}")
            return None

        try:
            latitude = float(fields[2])
            lat_direction = fields[3]
            longitude = float(fields[4])
            lon_direction = fields[5]
            altitude = float(fields[9])
            satellite_count = int(fields[7])

            latitude = latitude / 100.0
            if lat_direction == 'S':
                latitude = -latitude

            longitude = longitude / 100.0
            if lon_direction == 'W':
                longitude = -longitude

            return GPSReading(latitude, longitude, altitude, satellite_count)
        except (ValueError, IndexError) as e:
            logging.error(f"Error parsing GPGGA sentence: {sentence} - {e}")
            return None

    def read_gps(self) -> None:
        if not self.serial or not self.serial.is_open:
            logging.error("Serial port is not open")
            return

        while True:
            try:
                line = self.serial.readline().decode('utf-8').strip()
                if line.startswith('$GPGGA'):
                    reading = self.parse_gpgga(line)
                    if reading:
                        logging.info(f"Valid GPS reading: {reading}")
            except serial.SerialTimeoutException:
                logging.warning("Read timeout occurred")
            except Exception as e:
                logging.error(f"Unexpected error: {e}")

def signal_handler(sig, frame):
    logging.info("Received signal to exit")
    gps_reader.disconnect()
    exit(0)

if __name__ == "__main__":
    gps_reader = GPSReader()
    gps_reader.connect()

    if gps_reader.serial and gps_reader.serial.is_open:
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        gps_reader.read_gps()
    else:
        logging.error("Failed to start GPS reading loop")

