import serial
import time
import signal
import sys

class GPSModule:
    def __init__(self, port='/dev/ttyAMA0', baud=9600, timeout=1):
        self.port = port
        self.baud = baud
        self.timeout = timeout
        self.serial = None
        self._open_port()

    def _open_port(self):
        try:
            self.serial = serial.Serial(self.port, self.baud, timeout=self.timeout)
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to open serial port {self.port}: {e}")

    def attach(self):
        if not self.serial:
            raise RuntimeError("Serial port is not open")

        try:
            self.serial.write(b"AT+CGNSPWR=1\r\n")
            time.sleep(1)
            response = self.serial.readline().decode('utf-8').strip()
            if response != "OK":
                raise RuntimeError(f"Failed to power on GNSS: {response}")
        except serial.SerialException as e:
            raise RuntimeError(f"Serial write error: {e}")

    def detach(self):
        if not self.serial:
            raise RuntimeError("Serial port is not open")

        try:
            self.serial.write(b"AT+CGNSPWR=0\r\n")
            response = self.serial.readline().decode('utf-8').strip()
            if response != "OK":
                raise RuntimeError(f"Failed to power off GNSS: {response}")
        except serial.SerialException as e:
            raise RuntimeError(f"Serial write error: {e}")

    def get_data(self):
        if not self.serial:
            raise RuntimeError("Serial port is not open")

        try:
            data = self.serial.read_all().decode('utf-8')
            lines = data.splitlines()
            for line in lines:
                if line.startswith("$GPRMC"):
                    parts = line.split(',')
                    if len(parts) > 2 and parts[2] == "A":
                        return parts
        except serial.SerialException as e:
            raise RuntimeError(f"Serial read error: {e}")

        return None

    def close(self):
        if self.serial:
            self.serial.close()
            self.serial = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GPSModule() as gps:
        gps.attach()
        try:
            while True:
                data = gps.get_data()
                if data:
                    print("GPRMC Data:", data)
                time.sleep(1)
        except KeyboardInterrupt:
            print("Interrupted by user")
        finally:
            gps.detach()

