class SimpleGPS:
    def __init__(self, device='/dev/serial0', baudrate=9600):
        self.device = device
        self.baudrate = baudrate
        self.serial = None

    def connect(self):
        try:
            self.serial = serial.Serial(self.device, self.baudrate, timeout=1)
            logging.info(f"Connected to GPS module on {self.device} at {self.baudrate} baud")
            return True
        except OSError as e:
            logging.error(f"Failed to connect to GPS module: {e}")
            return False

    def read_data(self):
        if not self.serial or not self.serial.is_open:
            logging.error("Serial port is not open")
            return None
        try:
            data = self.serial.readline().decode('utf-8', errors='ignore').strip()
            if not data:
                return None
            return data
        except Exception as e:
            logging.error(f"Error reading data from GPS module: {e}")
            return None

    def parse_gga(self, line):
        if not line.startswith('$GPGGA') and not line.startswith('$GNGGA'):
            return None
        try:
            parts = line.split(',')
            utc_time = parts[1]
            latitude = self._parse_lat(parts[2], parts[3])
            longitude = self._parse_lon(parts[4], parts[5])
            fix_quality = int(parts[6])
            num_satellites = int(parts[7])
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA sentence: {e}")
            return None

    def _parse_lat(self, lat_str, lat_dir):
        if not lat_str or not lat_dir:
            return None
        try:
            lat_deg = float(lat_str[:2])
            lat_min = float(lat_str[2:])
            lat = lat_deg + lat_min / 60.0
            if lat_dir.upper() == 'S':
                lat = -lat
            return lat
        except ValueError:
            return None

    def _parse_lon(self, lon_str, lon_dir):
        if not lon_str or not lon_dir:
            return None
        try:
            lon_deg = float(lon_str[:3])
            lon_min = float(lon_str[3:])
            lon = lon_deg + lon_min / 60.0
            if lon_dir.upper() == 'W':
                lon = -lon
            return lon
        except ValueError:
            return None

    def close(self):
        if self.serial and self.serial.is_open:
            try:
                self.serial.close()
                logging.info("GPS module connection closed")
            except Exception as e:
                logging.error(f"Error closing GPS module connection: {e}")
            finally:
                self.serial = None

if __name__ == "__main__":
    gps = SimpleGPS()
    if not gps.connect():
        logging.error("Failed to connect to GPS module, exiting")
        exit(1)

    try:
        while True:
            data = gps.read_data()
            if data and data.startswith('$GPGGA') or data.startswith('$GNGGA'):
                parsed_data = gps.parse_gga(data)
                if parsed_data:
                    logging.info(f"Parsed GGA data: {parsed_data}")
            sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, shutting down")
    finally:
        gps.close()

