                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA sentence: {e}")
            return None

    def _parse_lat(self, lat_str, lat_dir):
        if not lat_str or not lat_dir:
            return None
        try:
            lat_deg = float(lat_str[:2])
            lat_min = float(lat_str[2:])
            lat = lat_deg + lat_min / 60.0
            if lat_dir.upper() == 'S':
                lat = -lat
            return lat
        except ValueError:
            return None

    def _parse_lon(self, lon_str, lon_dir):
        if not lon_str or not lon_dir:
            return None
        try:
            lon_deg = float(lon_str[:3])
            lon_min = float(lon_str[3:])
            lon = lon_deg + lon_min / 60.0
            if lon_dir.upper() == 'W':
                lon = -lon
            return lon
        except ValueError:
            return None

    def close(self):
        if self.serial and self.serial.is_open:
            try:
                self.serial.close()
                logging.info("GPS module connection closed")
            except Exception as e:
                logging.error(f"Error closing GPS module connection: {e}")
            finally:
                self.serial = None

if __name__ == "__main__":
    gps = SimpleGPS()
    if not gps.connect():
        logging.error("Failed to connect to GPS module, exiting")
        exit(1)

    try:
        while True:
            data = gps.read_data()
            if data and data.startswith('$GPGGA') or data.startswith('$GNGGA'):
                parsed_data = gps.parse_gga(data)
                if parsed_data:
                    logging.info(f"Parsed GGA data: {parsed_data}")
            sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, shutting down")
    finally:
        gps.close()
