from serial import Serial, SerialException, TimeoutException
from contextlib import contextmanager

app = Flask(__name__)
app.debug = False

# Thread-safe lock for UART access
uart_lock = threading.Lock()

# In-memory list of items
items = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True}
]

# Auto-incrementing ID
next_id = 3

# UART context manager
@contextmanager
def uart_context():
    uart = None
    try:
        uart = Serial('/dev/ttyUSB0', baudrate=9600, timeout=1)
        yield uart
    except SerialException as e:
        print(f"Failed to open UART: {e}")
        raise
    finally:
        if uart:
            uart.close()

# Signal handler to close UART and stop Flask
def signal_handler(sig, frame):
    print("Received signal, shutting down...")
    os._exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

