    try:
        with uart_lock:
            with uart_context() as uart:
                uart.write(b'*IDN?\n')
                uart.flush()
                response = uart.readline().decode('ascii').strip()
                if not response:
                    return "Timeout or no response", 504
                return response, 200
    except SerialException:
        return "Failed to open UART", 500
    except Exception as e:
        print(f"API call error: {e}")
        return "API call error", 502

@app.route('/data', methods=['GET'])
